-- More trails with real photos (schema demo). Photos: Wikimedia Commons.
begin;
insert into demo.trails (name, short_description, full_description, region, trail_type, length_km, duration_minutes, difficulty, accessibility, tags, estimated_price, start_lat, start_lng, end_lat, end_lng, waypoints, image_url, created_by, status, slug)
select 'מסלול חומות העיר העתיקה', 'הליכה על חומות העיר העתיקה, עם נוף אל הרובעים ואל העיר החדשה.', 'מסלול הליכה על גבי חומות העיר העתיקה בירושלים. מהחומה נשקפים הרובעים, הגגות והעיר החדשה. יש בו מדרגות רבות, ולכן הנגישות מוגבלת. מחיר הכניסה, האורך והקואורדינטות משוערים.', 'ירושלים', 'הליכה', 3, 120, 'medium'::difficulty, 2, array['היסטוריה','נוף','הליכה','צילום']::text[], 20, 31.7767, 35.2276, 31.7795, 35.2397, '[{"name":"שער יפו","lat":31.7767,"lng":35.2276}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/40/Old_City_Walls_of_Jerusalem_near_Zion_Gate%2C_showing_a_portion_of_the_Ramparts_Walk_southern_section.jpg/1280px-Old_City_Walls_of_Jerusalem_near_Zion_Gate%2C_showing_a_portion_of_the_Ramparts_Walk_southern_section.jpg', (select id from demo.profiles where name='Yosef Nachmany'), 'approved', public.next_unique_slug('demo','trails','מסלול חומות העיר העתיקה')
where not exists (select 1 from demo.trails where name='מסלול חומות העיר העתיקה');
insert into demo.trails (name, short_description, full_description, region, trail_type, length_km, duration_minutes, difficulty, accessibility, tags, estimated_price, start_lat, start_lng, end_lat, end_lng, waypoints, image_url, created_by, status, slug)
select 'טיילת יפו—בת ים', 'טיילת ארוכה לאורך חוף הים, מנמל יפו אל בת ים.', 'טיילת מישורית וארוכה לאורך חוף הים, מנמל יפו דרומה אל בת ים. נוחה להליכה, לאופניים ולעגלות, עם גישה לחופים ולבתי קפה. האורך משוער.', 'מרכז', 'הליכה', 6, 90, 'easy'::difficulty, 5, array['ים','משפחות','חינם','הליכה']::text[], 0, 32.0535, 34.75, 32.017, 34.744, '[{"name":"נמל יפו","lat":32.0535,"lng":34.75}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/28/94768_bat_yam_promenade_beach_PikiWiki_Israel.jpg/1280px-94768_bat_yam_promenade_beach_PikiWiki_Israel.jpg', (select id from demo.profiles where name='Daniel Lev'), 'approved', public.next_unique_slug('demo','trails','טיילת יפו—בת ים')
where not exists (select 1 from demo.trails where name='טיילת יפו—בת ים');
insert into demo.trails (name, short_description, full_description, region, trail_type, length_km, duration_minutes, difficulty, accessibility, tags, estimated_price, start_lat, start_lng, end_lat, end_lng, waypoints, image_url, created_by, status, slug)
select 'מסלול ההקפה באגמון החולה', 'מסלול נוח לאופניים או להליכה סביב אגמון החולה, בין ציפורים ומים.', 'מסלול הקפה מישורי באגמון החולה, שאפשר לעבור בהליכה או באופניים שנשכרים במקום. בעונת הנדידה אפשר לראות עגורים ועופות מים רבים. מחיר הכניסה והאורך משוערים.', 'צפון', 'אופניים', 8, 120, 'easy'::difficulty, 4, array['טבע','משפחות','נוף','צילום']::text[], 50, 33.0997, 35.6044, 33.096, 35.608, '[{"name":"כניסה לאגמון","lat":33.0997,"lng":35.6044}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/76/%D7%96%D7%A8%D7%99%D7%97%D7%94_%D7%91%D7%90%D7%92%D7%9E%D7%95%D7%9F_%D7%97%D7%95%D7%9C%D7%94_%D7%91%D7%96%D7%9E%D7%9F_%D7%A0%D7%93%D7%99%D7%93%D7%AA_%D7%94%D7%A2%D7%92%D7%95%D7%A8%D7%99%D7%9D.jpg/1280px-%D7%96%D7%A8%D7%99%D7%97%D7%94_%D7%91%D7%90%D7%92%D7%9E%D7%95%D7%9F_%D7%97%D7%95%D7%9C%D7%94_%D7%91%D7%96%D7%9E%D7%9F_%D7%A0%D7%93%D7%99%D7%93%D7%AA_%D7%94%D7%A2%D7%92%D7%95%D7%A8%D7%99%D7%9D.jpg', (select id from demo.profiles where name='Chana Ben David'), 'approved', public.next_unique_slug('demo','trails','מסלול ההקפה באגמון החולה')
where not exists (select 1 from demo.trails where name='מסלול ההקפה באגמון החולה');
insert into demo.trails (name, short_description, full_description, region, trail_type, length_km, duration_minutes, difficulty, accessibility, tags, estimated_price, start_lat, start_lng, end_lat, end_lng, waypoints, image_url, created_by, status, slug)
select 'שביל הנחש במצדה', 'עלייה תלולה אל פסגת מצדה, רצוי בשעות הבוקר המוקדמות.', 'שביל הנחש הוא השביל העתיק שעולה מהצד המזרחי אל פסגת מצדה. העלייה תלולה ומאומצת, ולכן מומלץ לצאת מוקדם בבוקר ולהצטייד במים. לא מתאים לכל מי שמוגבל בהליכה. האורך והמחיר משוערים.', 'ים המלח', 'טיפוס', 2.2, 90, 'hard'::difficulty, 1, array['היסטוריה','נוף','הליכה']::text[], 31, 31.317, 35.36, 31.3156, 35.3536, '[{"name":"תחילת השביל","lat":31.317,"lng":35.36}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9d/ISR-2016-Masada_04.jpg/1280px-ISR-2016-Masada_04.jpg', (select id from demo.profiles where name='Michal Roz'), 'approved', public.next_unique_slug('demo','trails','שביל הנחש במצדה')
where not exists (select 1 from demo.trails where name='שביל הנחש במצדה');
insert into demo.trails (name, short_description, full_description, region, trail_type, length_km, duration_minutes, difficulty, accessibility, tags, estimated_price, start_lat, start_lng, end_lat, end_lng, waypoints, image_url, created_by, status, slug)
select 'נחל ארוגות — המעיין הנסתר', 'הליכה לאורך נחל זורם במדבר יהודה, אל בריכות ומפל נסתר.', 'מסלול בנחל ארוגות, ליד עין גדי, לאורך נחל זורם בין מצוקים ואל בריכות מים ומפל. חלק מהמסלול כולל מעבר במים וסלעים. כדאי להצטייד בנעלי הליכה במים. האורך, המחיר והקואורדינטות משוערים.', 'ים המלח', 'מים', 4, 180, 'medium'::difficulty, 2, array['טבע','מים','הליכה','נוף']::text[], 28, 31.4528, 35.3917, 31.4467, 35.3794, '[{"name":"כניסה לנחל","lat":31.4528,"lng":35.3917}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/33/Nahal_Arugot_Stream_%28151422213%29.jpeg/1280px-Nahal_Arugot_Stream_%28151422213%29.jpeg', (select id from demo.profiles where name='Sara Cohen'), 'approved', public.next_unique_slug('demo','trails','נחל ארוגות — המעיין הנסתר')
where not exists (select 1 from demo.trails where name='נחל ארוגות — המעיין הנסתר');
insert into demo.trails (name, short_description, full_description, region, trail_type, length_km, duration_minutes, difficulty, accessibility, tags, estimated_price, start_lat, start_lng, end_lat, end_lng, waypoints, image_url, created_by, status, slug)
select 'שביל הירקון באופניים', 'רכיבה לאורך נהר הירקון מנמל תל אביב ועד מקורות הנהר.', 'מסלול אופניים לאורך נהר הירקון, מהים בתל אביב מזרחה אל אזור מקורות הנהר בראש העין. רובו מישורי ומתאים לרוכבים בכושר בינוני. האורך משוער.', 'מרכז', 'אופניים', 24, 150, 'medium'::difficulty, 4, array['טבע','מים','צילום']::text[], 0, 32.0975, 34.774, 32.0958, 34.9606, '[{"name":"נמל תל אביב","lat":32.0975,"lng":34.774}]'::jsonb, 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/65/Yarkon_River_in_the_Winter.jpg/1280px-Yarkon_River_in_the_Winter.jpg', (select id from demo.profiles where name='josh'), 'approved', public.next_unique_slug('demo','trails','שביל הירקון באופניים')
where not exists (select 1 from demo.trails where name='שביל הירקון באופניים');

commit;
